SELECT '0' tipo, '1' tipo2, ' Hoje' periodo, to_char(trunc(sysdate),'dd/mm/rrrr') datini, to_char(trunc(sysdate),'dd/mm/rrrr') datfin, 0 horini, 23 horfin,         sum(iec.pesoliquido) pesliq,         round(DECODE(SUM(A_PCTS.PESOLIQUIDO),0,0,SUM(A_PCTS.POL_CANA * A_PCTS.PESOLIQUIDO )/SUM(A_PCTS.PESOLIQUIDO) ),4) PCC,         round(DECODE(SUM(A_PCTS.PESOLIQUIDO),0,0,SUM(A_PCTS.ATR * A_PCTS.PESOLIQUIDO )/SUM(A_PCTS.PESOLIQUIDO) ),4) ATR,         round(DECODE(SUM(A_PCTS.PESOLIQUIDO),0,0,SUM(A_PCTS.AR_CANA * A_PCTS.PESOLIQUIDO )/SUM(A_PCTS.PESOLIQUIDO) ),4) AR,         round(DECODE(SUM(A_PCTS.PESOLIQUIDO),0,0,SUM(A_PCTS.PUREZA * A_PCTS.PESOLIQUIDO )/SUM(A_PCTS.PESOLIQUIDO) ),4) pureza,         round(DECODE(SUM(A_PCTS.PESOLIQUIDO),0,0,SUM(A_PCTS.FIBRA * A_PCTS.PESOLIQUIDO )/SUM(A_PCTS.PESOLIQUIDO) ),4) FIBRA,         trim(to_char(round(DECODE(SUM(iec.qtdehorasposqueima * decode(upper(tc.imprime_posqueima),'S',1,0)),0,0,                      SUM(iec.qtdehorasposqueima * decode(upper(tc.imprime_posqueima),'S',1,0) * iec.pesoliquido )/SUM(iec.pesoliquido)),2),'900'))||'h' tq,         round(DECODE(SUM(b.PESOLIQUIDO),0,0,SUM(b.impureza * 10 * b.PESOLIQUIDO )/SUM(b.PESOLIQUIDO) ),2) impmin,         round(DECODE(SUM(c.PESOLIQUIDO),0,0,SUM(c.impureza * 10 * c.PESOLIQUIDO )/SUM(b.PESOLIQUIDO) ),2) impveg  FROM agricola.entradacana ec,       agricola.itensentradacana iec,       agricola.analise_pcts a_pcts,       agricola.safra s,       agricola.ordem_corte_unica oc,       agricola.tipocana tc,       agricola.analise_imp_mineral b,       agricola.analise_imp_vegetal c  WHERE s.cod_grupoempresa = 1  AND   s.cod_empresa = 1  AND   s.cod_filial = 1  AND   s.cod_safra = :safra   AND   ec.cod_grupoempresa = s.cod_grupoempresa  AND   ec.cod_empresa = s.cod_empresa  AND   ec.cod_filial = s.cod_Filial  AND   ec.cod_safra = s.cod_Safra  AND   ec.datamovimento = trunc(sysdate)   AND   iec.cod_grupoempresa = ec.cod_grupoempresa  AND   iec.cod_empresa = ec.cod_empresa  AND   iec.cod_filial = 